class Greeting:
    def __init__(self, message):
        self.message = message
    def speak(self):
        raise NotImplementedError("子类必须实现此方法")
class HelloWorld(Greeting):
    def __init__(self):
        super().__init__("Hello, World!")
    def speak(self):
        print(self.message）
hw = HelloWorld()
hw.speak()

